 	while (begin < size) {
 		auto bytes = utf8proc_iterate(str + begin, size - begin, &codepoint);
 		D_ASSERT(bytes > 0);
 		if (utf8proc_category(codepoint) != UTF8PROC_CATEGORY_ZS) {
 			break;
 		}
 		begin += bytes;
