 data_ptr_t ArenaAllocator::Reallocate(data_ptr_t pointer, idx_t old_size, idx_t size) {
 	D_ASSERT(head);
 	if (old_size == size) {
 		// nothing to do
 		return pointer;
 	}

 	auto head_ptr = head->data.get() + head->current_position;
 	int64_t diff = size - old_size;
