 		// passed pointer is the head pointer, and the diff fits on the current chunk
 		head->current_position += diff;
 		return pointer;
 	} else {
 		// allocate new memory
 		auto result = Allocate(size);
 		memcpy(result, pointer, old_size);
 		return result;
 	}
