		HandleCastError::AssignError(error, error_message);
		return false;
	}
	return true;
}

bool TryCastHugeDecimalToNumeric(hugeint_t input, DST &result, string *error_message, uint8_t scale) {
	const auto power = Hugeint::POWERS_OF_TEN[scale];
