 			}
 			cout << query << std::endl;
 			REQUIRE(false);
 		}
 	}
 	REQUIRE_NO_FAIL(con.Query("DROP INDEX i_index"));
 	REQUIRE_NO_FAIL(con.Query("DROP TABLE numbers"));
