+double GetHue(const HighlightColorInfo &input) {
+	double r = input.r / 255.0;
+	double g = input.g / 255.0;
+	double b = input.b / 255.0;
+
+	double max = std::max({r, g, b});
+	double min = std::min({r, g, b});
+	double delta = max - min;
+
+	if (delta == 0) {
+		return 0;
+	}
+	double hue;
+	if (max == r) {
+		hue = (g - b) / delta;
+	} else if (max == g) {
+		hue = 2.0 + (b - r) / delta;
+	} else {
+		hue = 4.0 + (r - g) / delta;
+	}
+	hue *= 60.0;
+	if (hue < 0) {
+		hue += 360;
+	}
+	return hue;
+}
