		ADVANCE_STREAM(&ctx->Seed[i], skip_count);

	ADVANCE_STREAM(&ctx->Seed[P_CMNT_SD], skip_count * 2);
	ADVANCE_STREAM(&ctx->Seed[P_NAME_SD], skip_count * 92);

